P = json.load(open(f'{S}/fresh_products.json')); I = set(json.load(open(f'{S}/strict_issues.json'))['desc'])
UPD = 'mutation($p:ProductUpdateInput!){productUpdate(product:$p){userErrors{message}}}'
done, miss = 0, []
for p in P:
    if p['handle'] not in I: continue
    k = (p['vendor'], p['title'].split(',')[0].strip())
    if k not in D: miss.append(p['title']); continue
    e = gql(UPD, {'p': {'id': p['id'], 'descriptionHtml': f'<p>{H.escape(D[k])}</p>'}})['productUpdate']['userErrors']
    if e: print('ERR', p['title'], e)
    done += 1
print('updated', done, 'missing', miss)
